SHA256_RE = re.compile(r"[0-9A-F]{64}\Z")


class AuditError(RuntimeError):
    """A fail-closed certificate or witness error."""


def require(condition: bool, message: str) -> None:
    if not condition:
        raise AuditError(message)


def require_exact_keys(value: object, keys: set[str], label: str) -> dict[str, object]:
    require(type(value) is dict, f"{label} must be an object")
    mapping = value
    require(set(mapping) == keys, f"{label} keys differ from the pinned schema")
    return mapping


def require_int(value: object, label: str) -> int:
    require(type(value) is int, f"{label} must be an integer")
    return value


def require_expected_int(value: object, expected: int, label: str) -> int:
    actual = require_int(value, label)
    require(actual == expected, f"{label} mismatch")
    return actual


def require_int_list(value: object, length: int, label: str) -> list[int]:
    require(type(value) is list and len(value) == length, f"{label} must have length {length}")
    require(all(type(item) is int for item in value), f"{label} must contain only integers")
    return value


def require_int_matrix(value: object, rows: int, columns: int, label: str) -> list[list[int]]:
    require(type(value) is list and len(value) == rows, f"{label} must have {rows} rows")
    return [require_int_list(row, columns, f"{label}[{index}]") for index, row in enumerate(value)]


def require_sha(value: object, label: str) -> str:
    require(type(value) is str and SHA256_RE.fullmatch(value) is not None, f"{label} is not uppercase SHA-256")
    return value


def require_positive_decimal(value: object, label: str) -> int:
    require(type(value) is str and re.fullmatch(r"[1-9][0-9]*", value) is not None, f"{label} is not a positive decimal string")
    return int(value)


def reject_duplicate_keys(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise AuditError(f"duplicate JSON key: {key}")
        result[key] = value
    return result


def load_certificate(path: Path) -> dict[str, object]:
    require(path.is_file(), f"certificate not found: {path}")
    raw = path.read_bytes()
    require(len(raw) <= 1_000_000, "certificate unexpectedly large")
    require(raw.startswith(b"{") or raw.lstrip().startswith(b"{"), "certificate is not a JSON object")
